def monarchs(year):
    en=('EDWARD-III','Edward III','King of England','COC-EDWARD') if year<1377 else ('RICHARD-II','Richard II','King of England','COC-RICHARD') if year<1399 else ('HENRY-IV','Henry IV','King of England','COC-HENRY4') if year<1413 else ('HENRY-V','Henry V','King of England; claimant to the French crown','COC-HENRY5') if year<1422 else ('HENRY-VI','Henry VI','Infant king of England; French royal claim under the Treaty of Troyes' if year==1422 else 'King of England; continuing claim to the French crown','COC-HENRY6')
    fr=('PHILIP-VI','Philip VI','King of France','COC-FRENCH-KINGS') if year<1350 else ('JOHN-II','John II','King of France; captive' if year in (1356,1357,1359) else 'King of France','COC-FRENCH-KINGS') if year<1364 else ('CHARLES-V','Charles V','King of France','COC-CHARLES5') if year<1380 else ('CHARLES-VI','Charles VI','King of France','COC-BOOK') if year<1422 else ('CHARLES-VII','Charles VII','King of France; opposed by the Lancastrian royal claim','COC-BOOK')
    return en,fr

def record(statement, refs, cutoff, key, classification='historical_reference'):
    return {'id':key,'statement':statement,'source_ids':refs,'knowledge_scope':'historical_setup_reference','effective_not_after':cutoff,'classification':classification}

def registry(actors, year, day, refs):
    entities={};eligibility={}
    for a in actors:
        ident={k:a[k] for k in ('name','species','role')};ident['category']='person'
        entities[a['id']]={'id':a['id'],'kind':'character','versions':[{'start':day,'end':None,'source_ref':','.join(a['source_ids']),'exists':True,'identity':ident,'formation_time':None,'territory_refs':[],'resource_refs':[],'resources_status':'uninitialized'}]}
    en,fr=monarchs(year)
    for key,name,leader in [('ENGLAND','Kingdom of England','HYW-'+en[0]),('FRANCE','French royal government of '+fr[1],'HYW-'+fr[0])]:
        eid='HYW-'+key;entities[eid]={'id':eid,'kind':'faction','versions':[{'start':day,'end':None,'source_ref':','.join(refs),'exists':True,'identity':{'name':name,'category':'kingdom','government':'monarchy','leader_ids':[leader]},'formation_time':None,'territory_refs':[],'resource_refs':[],'resources_status':'uninitialized'}]}
    if year>=1422:
        entities['HYW-LANCASTRIAN-FRANCE']={'id':'HYW-LANCASTRIAN-FRANCE','kind':'faction','versions':[{'start':day,'end':None,'source_ref':'COC-HENRY6','exists':True,'identity':{'name':'Lancastrian claim to the French crown','category':'dynastic_claim','leader_ids':['HYW-HENRY-VI']},'formation_time':None,'territory_refs':[],'resource_refs':[],'resources_status':'uninitialized'}]}
    entities['HYW-CONFLICT']={'id':'HYW-CONFLICT','kind':'conflict','versions':[{'start':day,'end':None,'source_ref':'COC-BOOK','exists':True,'identity':{'name':'Anglo-French dynastic and territorial conflict','category':'historical_conflict_complex'},'formation_time':None,'territory_refs':[],'resource_refs':[],'resources_status':'uninitialized'}]}
    # Existence of the dispute does not certify current armed participation,
    # especially during the truces or the post-1453 continuation.
    for eid,e in entities.items():
        if e['kind']=='conflict':continue
        restricted_king=eid=='HYW-HENRY-VI' and year in (1422,1453)
        eligible=e['kind']=='character' and not restricted_king
        reason='Authored Solo policy allows voluntary declarations by this individual; office grants no operational mandate.' if eligible else 'Individual Solo control does not grant a polity or an infant adult agency.'
        if year==1453 and restricted_king:
            reason='Henry VI exists and retains his title; the documented 1453 incapacity prevents assuming voluntary control at this cutoff. No diagnosis or future recovery is imposed.'
        eligibility['individual:'+eid]={'entity_id':eid,'scenario_id':'individual','versions':[{'start':day,'end':None,'source_ref':'COC-DESIGN,COC-HENRY6-CAPACITY' if year==1453 and restricted_king else 'COC-DESIGN','eligible':eligible,'reason':reason,'control':{'mode':'individual','actor_ids':[eid] if eligible else [],'powers':['declare_own_intent'] if eligible else []}}]}
    return {'schema_version':1,'source_mode':'historical_template','axis':{'id':'julian-day','unit':'day','calendar':'julian'},'as_of':day,'entities':entities,'relations':{},'eligibility':eligibility,'scenarios':{'individual':{'id':'individual','title':'Solo · individual character','character_creation_allowed':True,'conflict_id':'HYW-CONFLICT','description':'One independent person; nationality, service, affiliation and actual control remain separate.'}}}

def main():
    PROV.mkdir(parents=True,exist_ok=True)
    cat=json.loads((DATA/'hyw_entry_catalogue.json').read_text(encoding='utf-8-sig'))
    entries={e['year']:e for e in cat['entries']}; rows=[line.split('|') for line in ROWS.strip().splitlines()]
    entries[1403].setdefault('source_title',entries[1403]['title'])
    entries[1403]['title']='The Welsh War and Channel Conflict'
    manifest=[]
    common_unknowns=[
      'No complete current census, local price list, household inventory, treasury, deployable army or maintained road network is established by this scoped opening.',
      'Exact personal locations, skills, health, loyalties and received reports remain unknown unless an explicit sourced or reviewed authored setup establishes them.',
      'The authored civil cutoff has day precision and no invented hour. It is not a claim that each background development occurred on that day.',
      'Culture, language, religion, legal status, office and personal allegiance are independent; no game category or appearance template determines them.',
      'The fictional local opening supplies a small playable scene only. General freeform, dialogue, combat and autonomous world advancement retain the actual runtime limits.'
    ]
    social=[
      'Household, parish, manor, town, court and service relationships overlap. Royal jurisdiction does not establish a household’s wealth or an individual’s consent.',
      'Use period and locality when establishing language, names, dress and religious practice. Neither kingdom is a homogeneous culture or ethnicity.',
      'Markets, credit, customs and obligations matter alongside harvests and transport. No universal conversion from GDP, grain yields or tax assessments into spendable stock is adopted.'
    ]
    for line in rows:
        year=int(line[0]);political,territorial,diplomatic,pressure,future=line[1:];e=entries[year]
        cutoff=f'{year}-12-15';refs=list(dict.fromkeys(['COC-BOOK',*EXTRA_SOURCES.get(year,[])]))
        actors=[]
        for key,name,role,sid in monarchs(year):actors.append({'id':'HYW-'+key,'name':name,'species':'human','role':role,'source_ids':[sid]})
        if year in EXTRAS:
            key,name,role=EXTRAS[year]
            if 'HYW-'+key not in {a['id'] for a in actors}:actors.append({'id':'HYW-'+key,'name':name,'species':'human','role':role,'source_ids':EXTRA_SOURCES.get(year,['COC-BOOK'])})
        used=list(dict.fromkeys(refs+[sid for a in actors for sid in a['source_ids']]+['COC-DESIGN','COC-LABOUR','COC-SCHISM','COC-SOLDIER-GUIDE','COC-JEWISH-ENGLAND','COC-LANGUAGE']))
        if year>=1415:used += ['COC-PAY']
        if year==1417:used += ['COC-CONSTANCE']
        if year==1453:used += ['COC-HENRY6-CAPACITY']
        material=[{'topic':'Recruitment and logistics','statement':'Musters, accounts, retinues and service periods need separate evidence. An indexed name is not proof of current presence, loyalty or readiness.','source_ids':['COC-SOLDIER-GUIDE'],'classification':'source_method'}]
        if year>=1351:
            material.append({'topic':'Labour and household economy','statement':'The 1349 ordinance and 1351 statute attempted to constrain wages and labour mobility after plague. Legal rules do not establish local compliance, individual status or market prices.','source_ids':['COC-LABOUR'],'classification':'historical_reference'})
        if year>=1364:
            material.append({'topic':'Language and law','statement':'The 1362 pleading statute forms part of changing legal language. French, English and Latin usage depends on context; a statute does not give everyone identical speech or literacy.','source_ids':['COC-LANGUAGE'],'classification':'historical_reference'})
        material.append({'topic':'Religion and legal status','statement':'England’s 1290 expulsion forms part of the legal background facing Jewish people. It does not prove universal absence, uniform identity or individual conduct. Locality and personal circumstances need evidence.','source_ids':['COC-JEWISH-ENGLAND'],'classification':'historical_reference'})
        if 1417<=year<=1450:
            material.append({'topic':'Documentary pay examples','statement':'For the described Normandy service, daily expectations were 6 sterling pence for an archer, 12 for a mounted man-at-arms and 8 for a foot man-at-arms. These are scoped documentary examples, not paid wages or universal market rates.','source_ids':['COC-PAY'],'classification':'documentary_reference_rate'})
        guide={'summary':[political,territorial], 'immediate_situation':[diplomatic,'This is an authored 15 December cutoff after the developments described above; subsequent history remains open.'],
          'player_options':['Create an independent character or select an eligible historical individual. Review the dated world and your actual control before saving.', 'A new human character may explicitly choose the fictional local delivery opening. You may observe, attempt either route, deliver the entrusted item or write your own response. No national allegiance or employment is compulsory.'],
          'practical_pressures':[pressure,*social], 'not_yet_established':common_unknowns,
          'future_rule':future+' The continuing campaign is never reset to another entry snapshot or forced to end in 1453.', 'source_ids':used}
        domains={key:[record(text,refs,cutoff,f'{e["id"]}-{key}-01')] for key,text in [('political',political),('military',pressure),('territorial',territorial),('diplomatic',diplomatic)]}
        # Practical pressures are authorial applications of the evidence.
        domains['military'][0]['classification']='research_inference'
        domains['military'][0]['source_ids']=['COC-DESIGN',*refs]
        day=julian_day(year,12,15)
        snap={'schema_version':1,'id':e['id'],'scenario_id':'hundred-years-war','revision':1,'status':'developed_historical_setup','title':e['title'],
          'opening':{'date':cutoff,'calendar':'julian','precision':'day','time':None,'boundary':'Authored late-year cutoff after the stated background developments; not their occurrence date.','label':f'15 December {year} · after the year’s turning points','classification':'authored_policy'},
          'briefing':political+' '+territorial+' '+diplomatic,'actors':actors,'domains':domains,'unknowns':common_unknowns,
          'sources':[copy.deepcopy(s) for s in SOURCES if s['id'] in used],
          'simulation_rules':['The snapshot initializes a new world only. Later facts come from actual committed campaign state.', 'Historical reference is out-of-character setup context, not automatically received character knowledge.', 'Personal identity and national allegiance are independent. No historical outcome, death, conversion or title transfer is scheduled.', 'Unknown quantities stay unknown. Authored fictional scene stock is explicitly reviewed and conserved through the existing Core.'],
          'entry_guide':guide,'entity_registry_template':registry(actors,year,day,refs),
          'research_extension':{'review_status':'scoped_source_comparison_not_complete_world_reconstruction','society':social,'economic_context':pressure,'material_context':material,
            'religious_context':('The Western Church is institutionally divided by rival papal obediences; local practice and personal adherence need their own evidence.' if 1378<=year<1417 else 'Martin V has been elected at Constance in November 1417, changing the institutional position after the schism. Recognition and local religious practice still need separate evidence.' if year==1417 else 'Ecclesiastical institutions and local religious practice are distinct from royal allegiance; personal adherence is not inferred.'),
            'quantities_status':'reference_units_and_documentary_examples_only; no default stocks or demographic interpolation',
            'conditional_development':{'statement':future,'classification':'research_inference','execution_available':False,'required_records':['living and capable participants','actual authority and intentions','received information','finite people, supplies, transport and finance','current local control and alternatives']}}}
        validate_registry(snap['entity_registry_template'],{a['id']:a for a in actors})
        name=f'hyw_{year}_opening.json';(DATA/name).write_text(json.dumps(snap,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        e.setdefault('source_title',e['title']);e.setdefault('source_description',e['description']);e['description']=political;e['status']='developed_historical_setup';e['snapshot_file']=name;e['opening_date']=cutoff;e['readiness_scope']='sourced_opening_and_optional_bounded_fictional_scene'
        manifest.append({'id':e['id'],'year':year,'date':cutoff,'source_ids':used,'people':len(actors),'scope':'bounded start; incomplete operational reconstruction'})
    # The pre-existing 1415 source and authored scene are preserved byte-for-byte.
    old=entries[1415];old['opening_date']='1415-08-11';old['readiness_scope']='sourced_opening_and_optional_bounded_fictional_scene'
    manifest.append({'id':old['id'],'year':1415,'date':'1415-08-11','preserved_existing_snapshot':True})
    cat.update(title='Century of Conflict: The Hundred-Years’ War',version='1.0',status='37 sourced scoped starting references with optional bounded local play',default_entry_id='hyw-1337',cutoff_policy='1415 preserves 11 August before departure; other entries use an explicitly authored 15 December checkpoint after the described developments. No opening hour is invented.')
    (DATA/'hyw_entry_catalogue.json').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    events=[]
    for e in cat['entries']:
        year=e['year']; event_id='coc.reference.'+str(year)
        statement=e['description'] if year!=1415 else 'Henry V prepared a cross-Channel expedition in 1415; subsequent events require their own evidence.'
        events.append({'id':event_id,'title':e['title'],'date':{'calendar':'julian','precision':'year','start':str(year)},
          'description':statement,'classification':'documented','research_status':'proposed_research',
          'source_refs':['COC-BOOK',*EXTRA_SOURCES.get(year,[])],
          'historical_outcome_reference':{'statement':statement,'classification':'documented','source_refs':['COC-BOOK',*EXTRA_SOURCES.get(year,[])]},
          'participants':[], 'conditions':[{'id':key,'type':'record_assertion','path':['evidence',event_id+':'+key,'status'],'expected':'established','requirement':'hard','classification':'design_inference','source_refs':['COC-DESIGN']} for key in ('participants-and-capacity','authority-and-decisions','received-information','resources-and-logistics','local-control-and-alternatives')], 'dependencies':[]})
    baseline={'schema_version':1,'id':'century-of-conflict-research-reference','revision':1,'scope':{'scenario_id':'hundred-years-war'},'status':'scoped_research_not_executable','sources':SOURCES,'events':events,
      'note':'Year windows are research references, not occurrence dates or schedules. Conditions require separate actual evidence and are not an exhaustive causal model. No arbitrary chain makes one historical outcome a prerequisite of all later events. Future personal deaths and campaign termination are never executed.'}
    from historical_plans import validate_baseline
    validate_baseline(baseline)
    (DATA/'coc_conditional_references.json').write_text(json.dumps(baseline,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (PROV/'opening_inventory.json').write_text(json.dumps({'edition':'century-starts-1','prepared':'2026-10-21','catalogue_entries':len(manifest),'featured_entries':cat['featured_years'],'entries':sorted(manifest,key=lambda r:r['year']),'sources':SOURCES,'historical_accuracy_limit':'Source-backed scoped contexts and explicit unknowns; not complete regional statistics or authentication of all earlier archive data.'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Built',len(rows),'new scoped snapshots; preserved 1415; catalogue',len(cat['entries']))

if __name__=='__main__':main()
